1	package ociresources
2	
3	import (
4		"net/http"
5		"net/http/httptest"
6		"net/url"
7		"slices"
8		"strings"
9		"sync/atomic"
10		"testing"
11	
12		"github.com/anthnel/devdesk/internal/cache"
13		"github.com/anthnel/devdesk/internal/config"
14		"github.com/anthnel/devdesk/internal/imagesearch"
15		"github.com/anthnel/devdesk/internal/ui/keymap"
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17	)
18	
19	// DEVDESK-311, step 2: the browser's lot shares catalog walks. Members of one
20	// batch that reach the same catalog with the same identity cost one request.
21	
22	// shareMembers are three members of one Nexus group on one host.
23	// This models a Nexus member catalog that Nexus 3.98.1 does not serve
24	// (measured, docs/measurements/2026-11-17-nexus-catalog.md; H1/IS-07). Kept as
25	// the UI contract until DEVDESK-579 decides how a member's catalog is reached.
26	var shareMembers = []string{"hosted", "proxy", "group"}
27	
28	// nexusGroupModel opens the browser on an anonymous Nexus group whose three
29	// discovered members all point at url, each with its own repo prefix.
30	//
31	// This models a Nexus member catalog that Nexus 3.98.1 does not serve
32	// (measured, docs/measurements/2026-11-17-nexus-catalog.md; H1/IS-07). Kept as
33	// the UI contract until DEVDESK-579 decides how a member's catalog is reached.
34	func nexusGroupModel(t *testing.T, url string) Model {
35		t.Helper()
36		group := nexusGroup()
37		group.AuthMode = config.AuthAnonymous
38		group.URL = url
39		cfg := testConfig()
40		cfg.Registry.Registries = []config.RegistryItem{group}
41		var members []cache.RegistryGroupMember
42		for _, p := range shareMembers {
43			members = append(members, cache.RegistryGroupMember{Alias: p, URL: url, RepoPrefix: p})
44		}
45		m := feed(t, New(cfg), testutil.Resize(200, 40),
46			ImagesListMsg{Images: imageFixtures()},
47			RegistryGroupCacheLoadedMsg{Entries: map[string]cache.RegistryGroupEntry{"nx": {Members: members}}},
48		)
49		m = feed(t, m, testutil.Key(keymap.Browser))
50		if m.registryBrowser == nil {
51			t.Fatal("'b' did not open the registry browser")
52		}
53		return m
54	}
55	
56	// runLot submits text, runs the whole lot and feeds every answer back.
57	func runLot(t *testing.T, m Model, text string, n int) Model {
58		t.Helper()
59		m, cmd := submitRaw(t, m, text)
60		if cmd == nil || m.registryBrowser.state != browserStateImages {
61			t.Fatalf("the search did not start (state %d)", m.registryBrowser.state)
62		}
63		results := runCmds(t, cmd)
64		for range n {
65			m = feed(t, m, recvResult(t, results))
66		}
67		return m
68	}
69	
70	// catalogRequests serves one shared /v2/_catalog whose names carry the member
71	// prefix (hosted/nginx, proxy/nginx-x, group/nginx-y).
72	//
73	// This models a Nexus member catalog that Nexus 3.98.1 does not serve
74	// (measured, docs/measurements/2026-11-17-nexus-catalog.md; H1/IS-07). Kept as
75	// the UI contract until DEVDESK-579 decides how a member's catalog is reached.
76	func catalogRequests(t *testing.T, status int) (*httptest.Server, *atomic.Int32) {
77		t.Helper()
78		var n atomic.Int32
79		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
80			if r.URL.Path != "/v2/_catalog" {
81				http.NotFound(w, r)
82				return
83			}
84			n.Add(1)
85			if status != http.StatusOK {
86				http.Error(w, "down", status)
87				return
88			}
89			w.Header().Set("Content-Type", "application/json")
90			_, _ = w.Write([]byte(`{"repositories":["hosted/nginx","proxy/nginx-x","group/nginx-y","other/nginx"]}`))
91		}))
92		t.Cleanup(srv.Close)
93		return srv, &n
94	}
95	
96	// This models a Nexus member catalog that Nexus 3.98.1 does not serve
97	// (measured, docs/measurements/2026-11-17-nexus-catalog.md; H1/IS-07). Kept as
98	// the UI contract until DEVDESK-579 decides how a member's catalog is reached.
99	func TestThreeNexusMembersOnOneCatalogWalkItOnce(t *testing.T) {
100		srv, walks := catalogRequests(t, http.StatusOK)
101		withImageSearcher(t, wiredLikeProduction(srv))
102	
103		m := runLot(t, nexusGroupModel(t, srv.URL), "nginx", 3)
104	
105		if n := walks.Load(); n != 1 {
106			t.Errorf("/v2/_catalog got %d requests, want 1", n)
107		}
108		got := m.RegistryBrowserOutcomes()
109		for _, p := range shareMembers {
110			key := memberKey("nx", srv.URL, p)
111			if o, ok := got[key]; !ok || o.Verdict != imagesearch.VerdictOK {
112				t.Errorf("outcome of %s = %+v (present %v), want ok", key, o, ok)
113			}
114		}
115		rows := rowsOf(m)
116		if len(rows) != 3 {
117			t.Fatalf("rows = %v, want 3", rows)
118		}
119		for _, p := range shareMembers {
120			want := memberKey("nx", srv.URL, p) + ":" + p + "/"
121			if n := countPrefix(rows, want); n != 1 {
122				t.Errorf("rows under %q = %d in %v, want 1 (own prefix only)", want, n, rows)
123			}
124		}
125		for _, r := range rows {
126			if strings.Contains(r, ":other/") {
127				t.Errorf("row %q is outside every member prefix", r)
128			}
129		}
130		_, vals := headerLines(m)
131		want := "nx/hosted, nx/proxy, nx/group"
132		if vals["Cached only"] != want {
133			t.Errorf("Cached only = %q, want %q", vals["Cached only"], want)
134		}
135	}
136	
137	func countPrefix(rows []string, prefix string) int {
138		n := 0
139		for _, r := range rows {
140			if strings.HasPrefix(r, prefix) {
141				n++
142			}
143		}
144		return n
145	}
146	
147	// This models a Nexus member catalog that Nexus 3.98.1 does not serve
148	// (measured, docs/measurements/2026-11-17-nexus-catalog.md; H1/IS-07). Kept as
149	// the UI contract until DEVDESK-579 decides how a member's catalog is reached.
150	func TestAFailedSharedWalkFailsEveryMemberWithOneRequest(t *testing.T) {
151		srv, walks := catalogRequests(t, http.StatusServiceUnavailable)
152		withImageSearcher(t, wiredLikeProduction(srv))
153	
154		m := runLot(t, nexusGroupModel(t, srv.URL), "nginx", 3)
155	
156		if n := walks.Load(); n != 1 {
157			t.Errorf("/v2/_catalog got %d requests, want 1", n)
158		}
159		for _, p := range shareMembers {
160			wantVerdict(t, m, memberKey("nx", srv.URL, p), imagesearch.VerdictFailed)
161		}
162		_, vals := headerLines(m)
163		for _, p := range shareMembers {
164			if !strings.Contains(vals["Failed"], "nx/"+p) {
165				t.Errorf("Failed = %q, want it to list nx/%s", vals["Failed"], p)
166			}
167		}
168	}
169	
170	func TestTwoIdentitiesOnOneURLWalkTwice(t *testing.T) {
171		srv, walks := catalogRequests(t, http.StatusOK)
172		withImageSearcher(t, wiredLikeProduction(srv))
173		u, err := url.Parse(srv.URL)
174		if err != nil {
175			t.Fatal(err)
176		}
177		writeDockerConfig(t, map[string]any{
178			"auths": map[string]any{u.Host: map[string]string{"auth": encodeAuth("alice", "s3cret")}},
179		})
180		authed := config.RegistryItem{URL: srv.URL, Alias: "authed", Slug: "authed", AuthMode: config.AuthCredentials}
181	
182		m := registryModel(t, anonymousRegistry(srv.URL, "anon"), authed)
183		m = runLot(t, m, "nginx", 2)
184	
185		if n := walks.Load(); n != 2 {
186			t.Errorf("/v2/_catalog got %d requests, want 2 (one per identity)", n)
187		}
188		wantVerdict(t, m, "anon", imagesearch.VerdictOK)
189		wantVerdict(t, m, "authed", imagesearch.VerdictOK)
190	}
191	
192	// This models a Nexus member catalog that Nexus 3.98.1 does not serve
193	// (measured, docs/measurements/2026-11-17-nexus-catalog.md; H1/IS-07). Kept as
194	// the UI contract until DEVDESK-579 decides how a member's catalog is reached.
195	func TestTwoSuccessiveSearchesWalkTwice(t *testing.T) {
196		srv, walks := catalogRequests(t, http.StatusOK)
197		withImageSearcher(t, wiredLikeProduction(srv))
198	
199		m := runLot(t, nexusGroupModel(t, srv.URL), "nginx", 3)
200		b := m.registryBrowser
201		_, cmd := b.startImageSearch("nginx", slices.Clone(b.entries))
202		results := runCmds(t, cmd)
203		for range 3 {
204			recvResult(t, results)
205		}
206		if n := walks.Load(); n != 2 {
207			t.Errorf("/v2/_catalog got %d requests over two searches, want 2 (no cache between searches)", n)
208		}
209	}
210	
211	// A walk still in flight when a new lot replaces its lot gives the new lot no
212	// late result: the generation drops the old answer.
213	//
214	// This models a Nexus member catalog that Nexus 3.98.1 does not serve
215	// (measured, docs/measurements/2026-11-17-nexus-catalog.md; H1/IS-07). Kept as
216	// the UI contract until DEVDESK-579 decides how a member's catalog is reached.
217	func TestALateWalkOfAReplacedLotGivesTheNewLotNothing(t *testing.T) {
218		release := make(chan struct{})
219		entered := make(chan struct{}, 8)
220		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
221			entered <- struct{}{}
222			select {
223			case <-release:
224			case <-r.Context().Done():
225			}
226			_, _ = w.Write([]byte(`{"repositories":["hosted/nginx"]}`))
227		}))
228		t.Cleanup(srv.Close)
229		t.Cleanup(func() { close(release) })
230		withImageSearcher(t, wiredLikeProduction(srv))
231	
232		m, cmd := submitRaw(t, nexusGroupModel(t, srv.URL), "nginx")
233		old := runCmds(t, cmd)
234		<-entered
235		oldGen := m.registryBrowser.gen
236	
237		// The new lot replaces the old one (and cancels its context).
238		b := m.registryBrowser
239		b.startImageSearch("nginx", nil)
240		if b.gen == oldGen {
241			t.Fatal("the new lot kept the old generation")
242		}
243		late := recvResult(t, old)
244		m = feed(t, m, late)
245		if rows := rowsOf(m); len(rows) != 0 {
246			t.Errorf("rows = %v, want none from the replaced lot", rows)
247		}
248		if got := m.RegistryBrowserOutcomes(); len(got) != 0 {
249			t.Errorf("outcomes = %v, want none from the replaced lot", got)
250		}
251	}
