func TestAOneCharacterQuerySkipsThePrivateEntryAndAsksHub(t *testing.T) {
	hub, hubRequests := fakeHub(t)
	priv, privRequests := catalogServer(t, "api", "alpha")
	withImageSearcher(t, wiredLikeProduction(hub))

	m := registryModel(t,
